SELECT * FROM (SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, DATE_TRUNC('MONTH', paid_at) AS paid_month, ROUND(AVG(amount), 2) AS avg_amount, MAX(paid_at) AS latest_paid_at FROM payments GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_TRUNC('MONTH', paid_at)) AS agg WHERE avg_amount > 34;
